import Foundation

/// 界面快照的基线指纹（24×24 RGB 降采样的 base64）。
///
/// 录制方式：`FLAREMO_RECORD_SNAPSHOTS=1 swift test --filter SnapshotTests`，
/// 把打印出来的 `SNAPSHOT name=… hash=…` 抄进来（现在这张表就是这么来的）。
/// **什么时候该重新录**：有意改了视觉之后。随手改基线来掩盖回归是很快的，
/// 所以每一次更新都要在提交信息里写清楚「为什么样子变了」。
///
/// 为什么不是 PNG：二进制进仓库会越来越大、review 时看不见、冲突了没法合。
/// 24×24 只留结构不留细节，足够抓「布局塌了 / 颜色错了 / 少画一块」。
enum SnapshotBaselines {
    static let hashes: [String: String] = [
        "memo-card": "",
        "memo-detail": "",
        "memo-timeline": "",
        "quick-light": "",
        "reading-light": "",
    ]
}
